"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["65557"],{26678(e){e.exports=JSON.parse('{"id":"V4-046","slug":"laffer-curve","term":"Laffer Curve","also_known_as":[],"difficulty":"Intermediate","definition":"The Laffer curve is an economic idea showing that tax revenue rises as tax rates increase from zero, reaches a maximum, and then falls as rates become so high that they discourage work, investment and reporting of income.","explanation":["At a tax rate of 0%, the government collects no revenue. At 100%, there would be little incentive to earn taxable income, so revenue would also be close to zero. Somewhere in between lies a rate that raises the most revenue.","The idea is associated with economist Arthur Laffer, who popularised it in the 1970s, although the concept is much older. It became influential in supply-side economics and US tax policy in the 1980s.","For example, if a very high top tax rate causes wealthy people to move income abroad, delay selling assets or work less, cutting that rate could, in principle, increase revenue.","The Laffer curve is widely accepted in principle, but there is much debate about where actual tax rates sit on it. Most economists believe that, for most taxes in most countries, rates are below the revenue-maximising level, so tax cuts usually reduce revenue rather than increase it, although the effect depends on the tax and the behaviour of taxpayers."],"note":"","total":1725,"prev":{"slug":"labor-force-participation-rate","term":"Labor Force Participation Rate"},"next":{"slug":"lagging-indicator","term":"Lagging Indicator"}}')}}]);